import{_ as i,o as a,c as s,a2 as t}from"./chunks/framework.DUFi_nbG.js";const u=JSON.parse('{"title":"F2: Real-Time Optical Frame Loop & Debounce Heuristics","description":"","frontmatter":{},"headers":[],"relativePath":"features/F2-frame-loop-debounce.md","filePath":"features/F2-frame-loop-debounce.md"}'),o={name:"features/F2-frame-loop-debounce.md"};function n(r,e,c,l,d,p){return a(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="f2-real-time-optical-frame-loop-debounce-heuristics" tabindex="-1">F2: Real-Time Optical Frame Loop &amp; Debounce Heuristics <a class="header-anchor" href="#f2-real-time-optical-frame-loop-debounce-heuristics" aria-label="Permalink to &quot;F2: Real-Time Optical Frame Loop &amp; Debounce Heuristics&quot;">​</a></h1><h2 id="_1-description-debounce-logic" tabindex="-1">1. Description &amp; Debounce Logic <a class="header-anchor" href="#_1-description-debounce-logic" aria-label="Permalink to &quot;1. Description &amp; Debounce Logic&quot;">​</a></h2><p>Inside <code>ChefVideoPlayer.jsx</code>, an active <code>requestAnimationFrame</code> loop continuously checks if a new video frame is ready (<code>readyState === 4</code>). Detected gestures are filtered through two safety gates:</p><ol><li><strong>Confidence Threshold</strong>: $Score &gt; 0.75$ (rejects ambiguous hand poses).</li><li><strong>Time-Decay Debounce</strong>: $Date.now() - lastActionTime &gt; 1500ms$ (prevents rapid-fire toggling).</li></ol><h2 id="_2-heuristic-filter-flow" tabindex="-1">2. Heuristic Filter Flow <a class="header-anchor" href="#_2-heuristic-filter-flow" aria-label="Permalink to &quot;2. Heuristic Filter Flow&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Frame[New Optical Video Frame] --&gt; Ready{readyState == 4?}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Ready --&gt;|No| NextTick[Skip to Next RAF]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Ready --&gt;|Yes| Recognize[recognizeVideo Frame]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Recognize --&gt; ConfCheck{Confidence &gt; 0.75?}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ConfCheck --&gt;|No| Discard[Discard Ambiguous Pose]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ConfCheck --&gt;|Yes| TimeCheck{Elapsed Time &gt; 1500ms?}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    TimeCheck --&gt;|No| Throttle[Suppress: Debounce Active]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    TimeCheck --&gt;|Yes| FireAction[Execute Video Action &amp; Reset Timer]</span></span></code></pre></div><h2 id="_3-say-it-out-loud" tabindex="-1">3. Say It Out Loud <a class="header-anchor" href="#_3-say-it-out-loud" aria-label="Permalink to &quot;3. Say It Out Loud&quot;">​</a></h2><p>&quot;One of the biggest challenges in optical gesture control is preventing accidental double-triggers, known as gesture flapping. I solved this by implementing two distinct heuristic gates. First, any gesture classification with less than 75% confidence is discarded immediately. Second, I introduced a 1500ms time-decay debounce window stored in a React ref. Once a command like Pause fires, the system temporarily suppresses subsequent gesture executions for 1.5 seconds, giving the user ample time to lower their hand naturally without accidentally un-pausing the video.&quot;</p>`,8)])])}const m=i(o,[["render",n]]);export{u as __pageData,m as default};
